      Mb (Z_to_bv 64 a) = Ma (Z_to_bv 64 a))
  /\ (forall x, 0 <= x -> x + 1 <= 2 ^ 47 -> (x + 1 <= F \/ F + 128 <= x) -> Mb (Z_to_bv 64 (HeapIfaceA.S x)) = Ma (Z_to_bv 64 (HeapIfaceA.S x))).
